 65       if (request.method === 'GET') return sendJson(response, 200, await workspace.loadRecords(url.searchParams.get('history') === 'current' ? 'current' : 'all'));
 66       if (request.method === 'POST') return sendJson(response, 200, await workspace.applyBatch(await readBody(request, 64 * 1024 * 1024) as WorkspaceBatch));
 67       return sendJson(response, 405, { error: 'method not allowed' });
 68     }
 69     if (url.pathname === '/api/mapping/workspace/export') {
 70       if (request.method !== 'POST') return sendJson(response, 405, { error: 'method not allowed' });
 71       return sendJson(response, 200, await workspace.portableExport(await readBody(request, 64 * 1024 * 1024)));
 72     }
 73     if (url.pathname === '/api/mapping/workspace/import-contexts') {
 74       if (request.method !== 'POST') return sendJson(response, 405, { error: 'method not allowed' });
 75       return sendJson(response, 200, await workspace.prepareImport(await readBody(request, 64 * 1024 * 1024)));
 76     }
 77     if (url.pathname === '/api/mapping/workspace') {
 78       if (request.method === 'GET') return sendJson(response, 200, await workspace.load());
 79       if (request.method !== 'PUT') return sendJson(response, 405, { error: 'method not allowed' });
 80       // Workspace saves include revision histories and captured source evidence.
 81       return sendJson(response, 200, await workspace.save(await readBody(request, 64 * 1024 * 1024)));
 82     }
 83     if (url.pathname === '/api/mapping/chat') return handleLocalChat(request, response, chat);
 84     if (url.pathname === '/api/mapping/diagrams/publish' && request.method === 'POST')
 85       return sendJson(response, 200, await diagrams.publishCheckpoint(await readBody(request) as import('../../../../domain/core/diagrams/checkpointPublication').CheckpointPublication));
 86     if (url.pathname === '/api/mapping/diagrams') {
 87       if (request.method !== 'POST') return sendJson(response, 405, { error: 'method not allowed' });
 88       return sendJson(response, 200, await diagrams.save(await readBody(request) as SaveProjectDiagramInput));
 89     }
 90     const diagram = url.pathname.match(/^\/api\/mapping\/diagrams\/([^/]+)$/);
 91     if (diagram) {
 92       if (request.method !== 'DELETE') return sendJson(response, 405, { error: 'method not allowed' });
 93       return sendJson(response, 200, await diagrams.delete(decodeURIComponent(diagram[1])));
 94     }
 95     if (url.pathname === '/api/mapping/prompt') {
 96       if (request.method !== 'POST') return sendJson(response, 405, { error: 'method not allowed' });
 97       const input = await selection.prepare(await readBody(request) as Record<string, unknown>);
 98       response.statusCode = 200;
 99       response.setHeader('content-type', 'application/x-ndjson; charset=utf-8');
100       response.setHeader('cache-control', 'no-cache, no-transform');
101       response.flushHeaders();
102       const result = await selection.run(input, event => sendEvent(response, { type: 'progress', ...event }));
103       sendEvent(response, { type: 'result', result });
104       response.end();
105       return;
106     }
107     return sendJson(response, 404, { error: 'API route not found' });
108   };
109 }

